public static <T extends Comparable<T>> // generic static method
       int binarySearch(T[] array, T target) {
  int left = 0; 
// left index
  int right = array.length – 1; 
// right index
  while (left <= right) { 
// more elements to search
    int mid = (left + right) / 2; 
// middle index
    int c = target.compareTo(array[mid]);
    if (c == 0) return mid; 
// found at mid index
    else if (c < 0) right = mid – 1; 
// Search left half
    else left = mid + 1; 
// Search right half
  }
  return -1; 
// Element not found
}

