// Sorts the specified array using the bubble sort algorithm
public static <T extends Comparable<T>>
              void bubbleSort(T[] array) {
  for (int pass = 1; pass < array.length; pass++) {
    boolean sorted = true;
                                    // checks if the array is sorted
    for (int i = 0; i < array.length - pass; i++)
      if (array[i].compareTo(array[i+1]) > 0) {
        T temp = array[i];
        array[i] = array[i+1];
                                    // swap array[i] with array[i+1]
        array[i+1] = temp;
        sorted = false;
                                    // because swapping is done
      }
    if (sorted) break;
                                    // if sorted, terminate loop
  }
}

