// Used by quicksort to partition a generic array of elements
private static <T extends Comparable<T>>
        int partition(T[] array, int low, int high) {
  T pivot = array[high];
                                    // Use the high element as pivot
  int i = low;
  // Skip the elements that are smaller than the pivot
  while (array[i].compareTo(pivot) < 0) i++;
  for (int j=i+1; j<high; j++)
    if (array[j].compareTo(pivot) < 0) {
      swap(array, i, j);
                                    // swap if array[j] < pivot
      i++;
                                    // array[i] >= pivot
    }
  swap(array, i, high);
                                    // Move the pivot element
  return i;
                                    // Return the index of the pivot
}

