// Merges two sorted subarrays (low to mid) and (mid+1 to high)
private static <T extends Comparable<T>>
        void merge(T[] array, int low, int mid, int high) {
  T[] temp = (T[]) new Comparable[high-low+1]; // new temporary array
  int i = low;
                                        // index for first subarray
  int j = mid+1;
                                        // index for second subarray
  int k = 0;
                                        // index for temp array
  //  Copy smaller element from each subarray into temp array
  while (i <= mid && j <= high)
    if (array[i].compareTo(array[j]) < 0) temp[k++] = array[i++];
    else temp[k++] = array[j++];
  //  Copy remaining elements from the first and second subarray
  while (i <= mid) temp[k++] = array[i++];
  while (j <= high) temp[k++] = array[j++];
  //  Copy merged temporary array into original array
  for (i = low; i <= high; i++) array[i] = temp[i-low];
}

