public static void radixSort(int[] array, int maxdigits) {
  // pos is the position weight = 1, 10, 100, etc.
  for (int pass=1, pos=1; pass <= maxdigits; pass++, pos *= 10) {
    int[] count = new int[10];
                                            // 10 counters for digits 0 to 9
    for (int element : array) count[(element / pos) % 10]++;
    int[] index = new int[10];
                                            // 10 indexes for digits 0 to 9
    for (int i = 0; i < 9; i++) index[i+1] = index[i] + count[i];
    // Sort the array elements by mapping them to their correct indexes
    int[] sortarray = new int[array.length];
    for (int element : array) {
      int digit = (element/pos) % 10;
                                            // digit at a given position
      sortarray[index[digit]] = element;
      index[digit]++;
    }
    System.arraycopy(sortarray, 0, array, 0, array.length);
  }
}

